import{H as e,N as t,O as n,j as r,n as i}from"./chunks/framework.CPTEkitH.js";var a=JSON.parse(`{"title":"DeepMind & Singapore Gov Tackle Scams with On-Device AI","description":"Google DeepMind partners with GovTech Singapore to deploy lightweight Gemma models directly on devices. This initiative aims to detect conversational scams privately, ensuring no user data leaves the device.","frontmatter":{"layout":"article","title":"DeepMind & Singapore Gov Tackle Scams with On-Device AI","description":"Google DeepMind partners with GovTech Singapore to deploy lightweight Gemma models directly on devices. This initiative aims to detect conversational scams privately, ensuring no user data leaves the device.","photo":"https://picsum.photos/id/114/800/450","original_url":"https://deepmind.google/blog/on-device-ai-scam-detection-mddi/","source_name":"Google DeepMind Blog","source_author":"","tags":["ai","llm","google","deepmind"],"significance":3,"head":[["link",{"rel":"canonical","href":"https://digestweb.dev/articles/2026-10-14/deepmind-singapore-gov-on-device-ai-scam-detection"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"DeepMind & Singapore Gov Tackle Scams with On-Device AI"}],["meta",{"property":"og:description","content":"Google DeepMind partners with GovTech Singapore to deploy lightweight Gemma models directly on devices. This initiative aims to detect conversational scams privately, ensuring no user data leaves the device."}],["meta",{"property":"og:url","content":"https://digestweb.dev/articles/2026-10-14/deepmind-singapore-gov-on-device-ai-scam-detection"}],["meta",{"property":"og:site_name","content":"digestweb.dev"}],["meta",{"property":"og:image","content":"https://picsum.photos/id/114/800/450"}],["meta",{"property":"article:published_time","content":"2026-10-14T00:00:00.000Z"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"DeepMind & Singapore Gov Tackle Scams with On-Device AI"}],["meta",{"name":"twitter:description","content":"Google DeepMind partners with GovTech Singapore to deploy lightweight Gemma models directly on devices. This initiative aims to detect conversational scams privately, ensuring no user data leaves the device."}],["meta",{"name":"twitter:image","content":"https://picsum.photos/id/114/800/450"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"NewsArticle\\",\\"headline\\":\\"DeepMind & Singapore Gov Tackle Scams with On-Device AI\\",\\"description\\":\\"Google DeepMind partners with GovTech Singapore to deploy lightweight Gemma models directly on devices. This initiative aims to detect conversational scams privately, ensuring no user data leaves the device.\\",\\"url\\":\\"https://digestweb.dev/articles/2026-10-14/deepmind-singapore-gov-on-device-ai-scam-detection\\",\\"datePublished\\":\\"2026-10-14T00:00:00.000Z\\",\\"image\\":\\"https://picsum.photos/id/114/800/450\\",\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"digestweb.dev\\",\\"url\\":\\"https://digestweb.dev\\"}}"]]},"headers":[],"relativePath":"articles/2026-10-14/deepmind-singapore-gov-on-device-ai-scam-detection.md","filePath":"articles/2026-10-14/deepmind-singapore-gov-on-device-ai-scam-detection.md"}`),o={name:`articles/2026-10-14/deepmind-singapore-gov-on-device-ai-scam-detection.md`};function s(i,a,o,s,c,l){return e(),r(`div`,null,[...a[0]||=[n(`h2`,{id:`summary-key-takeaways`,tabindex:`-1`},[t(`Summary & Key Takeaways `),n(`a`,{class:`header-anchor`,href:`#summary-key-takeaways`,"aria-label":`Permalink to “Summary & Key Takeaways”`},`​`)],-1),n(`p`,null,`Google DeepMind and GovTech Singapore are collaborating on an AI-powered scam detection system. The system utilizes lightweight Gemma models running directly on user devices. This on-device approach ensures conversational data remains private with zero cloud egress. The initiative aims to intercept sophisticated conversational scams effectively. This project demonstrates a practical application of AI for public safety and privacy. The models are fine-tuned for specific scam patterns. This collaboration highlights the potential of localized AI processing. It offers a new paradigm for secure and private AI deployments.`,-1),n(`h2`,{id:`our-commentary`,tabindex:`-1`},[t(`Our Commentary `),n(`a`,{class:`header-anchor`,href:`#our-commentary`,"aria-label":`Permalink to “Our Commentary”`},`​`)],-1),n(`p`,null,`We've been talking about on-device AI for a while, but this feels like a genuinely impactful application. Scam detection is a huge problem, and the privacy-first approach here is critical. I'm always wary of AI solutions that demand all our data, so seeing 'zero cloud data egress' is a breath of fresh air. It makes me wonder how much more we can push local processing for sensitive tasks. There's something really compelling about AI working silently in the background, protecting us without needing to phone home. It's a good step towards more trustworthy AI deployments, I think.`,-1)]])}var c=i(o,[[`render`,s]]);export{a as __pageData,c as default};